use super::*;

/// What to run to declare an account a statement just revealed.
///
/// A READY COMMAND, not a description of one. The gap between "you should declare this" and a line
/// somebody can paste is where the loop between ingest and the registry actually breaks — and an
/// agent driving this has no hands to go and look up the field names.
pub fn declare_hint(id: &str, institution: &str, kind: crate::account::Kind) -> String {
    format!(
        "echo '{{\"id\":\"{id}\",\"institution\":\"{institution}\",\"kind\":\"{}\"}}' | bsc fin account set",
        kind.as_str()
    )
}
